const Header = () => {
  const headerRef = useRef(null);
  const [isSticky, setIsSticky] = useState(false);
  const [openMenuIndex, setOpenMenuIndex] = useState(null);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [stampOpen, setStampOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    document.documentElement.setAttribute('lang', 'ar');
    document.documentElement.setAttribute('dir', 'rtl');
    document.body.classList.add('loged-user');

    const updateOffset = () => {
      if (headerRef.current) {
        document.documentElement.style.setProperty(
          '--balady-header-height',
          `${headerRef.current.offsetHeight}px`
        );
      }
    };

    updateOffset();
    window.addEventListener('resize', updateOffset);
    return () => {
      window.removeEventListener('resize', updateOffset);
      document.body.classList.remove('loged-user');
    };
  }, [mobileNavOpen, stampOpen, openMenuIndex]);

  useEffect(() => {
    const onScroll = () => {
      const headerHeight = headerRef.current?.offsetHeight ?? 0;
      setIsSticky(window.scrollY > headerHeight + 10);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
    };
  }, [mobileNavOpen, stampOpen, openMenuIndex]);

  useEffect(() => {
    const menuOpen = openMenuIndex !== null || mobileNavOpen;
    if (menuOpen) {
      document.body.classList.add('menu-dropdown-open');
    } else {
      document.body.classList.remove('menu-dropdown-open');
    }
    if (mobileNavOpen) {
      document.body.classList.add('side-menu-open');
    } else {
      document.body.classList.remove('side-menu-open');
    }
    return () => {
      document.body.classList.remove('menu-dropdown-open');
      document.body.classList.remove('side-menu-open');
    };
  }, [openMenuIndex, mobileNavOpen]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (!event.target.closest('.setting-header')) {
        setSettingsOpen(false);
      }
      if (!event.target.closest('.menu-item--expanded') && !event.target.closest('.dropdown-toggle')) {
        setOpenMenuIndex(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const onResize = () => {
      if (window.innerWidth >= 992) {
        setMobileNavOpen(false);
      }
    };
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  useEffect(() => {
    const onKeyDown = (event) => {
      if (event.key === 'Escape') {
        setMobileNavOpen(false);
        setOpenMenuIndex(null);
        setSearchOpen(false);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, []);

  useEffect(() => {
    if (mobileNavOpen || searchOpen) {
      document.body.classList.add('modal-open');
      document.body.style.overflow = 'hidden';
    } else {
      document.body.classList.remove('modal-open');
      document.body.style.overflow = '';
    }
    return () => {
      document.body.classList.remove('modal-open');
      document.body.style.overflow = '';
    };
  }, [mobileNavOpen, searchOpen]);

  const closeMobileNav = () => setMobileNavOpen(false);

  const toggleMobileNav = () => {
    setMobileNavOpen((open) => {
      const next = !open;
      if (next) {
        setOpenMenuIndex(null);
        setStampOpen(false);
        setSettingsOpen(false);
      }
      return next;
    });
  };

  const toggleMenu = (index) => {
    setOpenMenuIndex((prev) => (prev === index ? null : index));
  };

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      window.open(
        `https://balady.gov.sa/solr-serach-v1?search_api_fulltext=${encodeURIComponent(searchQuery.trim())}`,
        '_blank',
        'noopener,noreferrer'
      );
    }
  };

  return (
    <div className={`site-header-cont${isSticky ? ' sticky' : ''}`} ref={headerRef}>
      <header className="site-header inner-header-login">
        <div className="container-fluid">
          <nav className="navbar navbar-expand-lg">
            <a className="navbar-brand" href="https://balady.gov.sa/ar" target="_blank" rel="noopener noreferrer">
              <img
                className="logo"
                alt="logo"
                src="https://apps.balady.gov.sa/BALADYCDN/Content/Images/logo-light.svg"
                style={{ height: '40px' }}
              />
            </a>

            <header className={`mainHeader${mobileNavOpen ? ' inverted' : ''}`}>
              <div className="top-header-content">
                <div className="container top-header">
                  <div className="top-header-right">
                    <div className="digital-stamp-head">
                      <div className="digital-stamp-icon">{SAUDI_FLAG_SVG}</div>
                      <div className="digital-stamp-text">
                        <span>موقع حكومي مسجل لدى هيئة الحكومة الرقمية</span>
                      </div>
                      <button
                        type="button"
                        className={`digital-stamp-link ${stampOpen ? '' : 'collapsed'}`}
                        onClick={() => {
                          setStampOpen((v) => !v);
                          closeMobileNav();
                        }}
                        aria-expanded={stampOpen}
                        aria-controls="collapseDigitalStamp"
                      >
                        كيف تتحقق
                        <i className="hgi hgi-stroke hgi-rounded hgi-arrow-down-01" aria-hidden="true" />
                      </button>
                    </div>
                  </div>

                  <div className="top-header-left">
                    <div className="dropdown setting-header">
                      <button
                        className={`btn site-setting-btn ${settingsOpen ? 'show' : ''}`}
                        type="button"
                        aria-expanded={settingsOpen}
                        aria-label="الإعدادات"
                        onClick={() => {
                          setSettingsOpen((v) => !v);
                          closeMobileNav();
                        }}
                      >
                        {SETTINGS_ICON}
                        <span>الإعدادات</span>
                      </button>
                      {settingsOpen && (
                        <div className="dropdown-menu show">
                          <button type="button" className="dropdown-item">
                            الطباعة
                          </button>
                          <button type="button" className="dropdown-item">
                            حفظ الصفحة
                          </button>
                          <button type="button" className="dropdown-item">
                            ضبط إعدادات الإشعارات
                          </button>
                          <button type="button" className="dropdown-item">
                            استخدام التاريخ الهجري
                          </button>
                          <button type="button" className="dropdown-item">
                            استخدام التاريخ الميلادي
                          </button>
                        </div>
                      )}
                    </div>
                    <div id="munner-header">
                      <button className="btn muneer-trigger-btn icon-position-before" type="button" aria-label="أدوات سهولة الوصول">
                        {ACCESSIBILITY_ICON}
                        <span>أدوات سهولة الوصول</span>
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              <div className={`container digital-stamp-container ${stampOpen ? 'stamp-open' : ''}`}>
                <div className={`collapse ${stampOpen ? 'show' : ''}`} id="collapseDigitalStamp">
                  <div className="digital-stamp-content">
                    <div className="row g-3">
                      <div className="col-md-6">
                        <div className="ds-content_item">
                          <div className="ds-content_item_icon">
                            <i className="hgi hgi-stroke hgi-rounded hgi-link-04" aria-hidden="true" />
                          </div>
                          <div className="ds-content_item_content">
                            <h2>
                              روابط المواقع الالكترونية الرسمية السعودية تنتهي
                              <span>.gov.sa</span>
                            </h2>
                            <p>
                              جميع روابط المواقع الرسمية التابعة للجهات الحكومية في المملكة العربية السعودية تنتهي بـ .gov.sa
                            </p>
                          </div>
                        </div>
                      </div>
                      <div className="col-md-6">
                        <div className="ds-content_item">
                          <div className="ds-content_item_icon">
                            <i className="hgi hgi-stroke hgi-rounded hgi-square-lock-password" aria-hidden="true" />
                          </div>
                          <div className="ds-content_item_content">
                            <h2>
                              المواقع الالكترونية الحكومية تستخدم بروتوكول
                              <span>HTTPS</span> للتشفير و الأمان.
                            </h2>
                            <p>
                              المواقع الالكترونية الآمنة في المملكة العربية السعودية تستخدم بروتوكول HTTPS للتشفير.
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div className="digital-stamp-footer">
                    <div className="ds-footer_item_content">
                      <p>مسجل لدى هيئة الحكومة الرقمية برقم:</p>
                      <a
                        href="https://raqmi.dga.gov.sa/platforms/DigitalStamp/ShowCertificate/316"
                        className="ds-footer_link"
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <span className="link__label">20250428339</span>
                      </a>
                    </div>
                  </div>
                </div>
              </div>

              <div className="container-fluid">
                <div className="row">
                  <div className="col d-flex columns">
                    <div className="region region--header">
                      <div className="clearfix site-branding block block-system block-system-branding-block">
                        <a href="https://balady.gov.sa/ar" className="site-branding__logo" target="_blank" rel="home noopener noreferrer">
                          <img 
                            src="/logo.svg" 
                            alt="الرئيسية" 
                            style={{ padding: '4px', borderRadius: '4px' }} 
                          />
                        </a>
                      </div>
                    </div>

                    <nav className="navbar navbar-expand-lg position-static header-mobile-container">
                      <button
                        className={`navbar-toggler ${mobileNavOpen ? '' : 'collapsed'}`}
                        type="button"
                        aria-controls="navbarSupportedContent"
                        aria-expanded={mobileNavOpen}
                        aria-label="Toggle navigation"
                        onClick={toggleMobileNav}
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="#000000" viewBox="0 0 30 30" width="30px" height="30px">
                          <path d="M 3 7 A 1.0001 1.0001 0 1 0 3 9 L 27 9 A 1.0001 1.0001 0 1 0 27 7 L 3 7 z M 3 14 A 1.0001 1.0001 0 1 0 3 16 L 27 16 A 1.0001 1.0001 0 1 0 27 14 L 3 14 z M 3 21 A 1.0001 1.0001 0 1 0 3 23 L 27 23 A 1.0001 1.0001 0 1 0 27 21 L 3 21 z" />
                        </svg>
                      </button>

                      <div className={`collapse navbar-collapse ${mobileNavOpen ? 'show' : ''}`} id="navbarSupportedContent">
                        <div className="region region--header-content">
                          <nav aria-labelledby="block-balady-main-menu-menu" id="block-balady-main-menu" className="block block-menu navigation menu--main">
                            <h2 className="visually-hidden block-title" id="block-balady-main-menu-menu">
                              القائمة الرئيسية
                            </h2>
                            <div className="block-content">
                              <ul className="menu" aria-hidden="false">
                                {NAV_ITEMS.map((item, index) => (
                                  <li
                                    key={item.label}
                                    className={`menu-icon menu-item menu-item-first menu-level-0 menu-count-${item.menuCount || 1} ${item.hasDropdown ? 'menu-item--expanded dropdown' : ''
                                      } ${openMenuIndex === index ? 'show' : ''}`}
                                  >
                                    {item.hasDropdown ? (
                                      <>
                                        <a
                                          className="dropdown-toggle"
                                          href={item.path}
                                          role="button"
                                          aria-expanded={openMenuIndex === index}
                                          onClick={(e) => {
                                            e.preventDefault();
                                            toggleMenu(index);
                                          }}
                                        >
                                          <span>{item.label}</span>
                                        </a>
                                        <div className={`dropdown-menu ${openMenuIndex === index ? 'show' : ''}`}>
                                          <ul className="menu" aria-hidden="false">
                                            {item.subItems.map((group, groupIndex) =>
                                              group.isMoreLink ? (
                                                <li key="more" className="menu-item menu-level-1">
                                                  <a href={group.path} target="_blank" rel="noopener noreferrer">
                                                    {group.label}
                                                  </a>
                                                </li>
                                              ) : (
                                                <li
                                                  key={group.category || groupIndex}
                                                  className="menu-item menu-item--expanded menu-level-1"
                                                >
                                                  {group.category && <span>{group.category}</span>}
                                                  <ul className="menu" aria-hidden="false">
                                                    {group.items.map((sub) => (
                                                      <li key={sub.label} className="menu-item menu-level-2">
                                                        <a href={sub.path} target="_blank" rel="noopener noreferrer">
                                                          {sub.label}
                                                        </a>
                                                      </li>
                                                    ))}
                                                  </ul>
                                                </li>
                                              )
                                            )}
                                          </ul>
                                        </div>
                                      </>
                                    ) : (
                                      <a href={item.path} target="_blank" rel="noopener noreferrer">
                                        {item.label}
                                      </a>
                                    )}
                                  </li>
                                ))}
                              </ul>
                            </div>
                          </nav>
                        </div>
                      </div>

                      <div className="header-left header-left_hide">
                        <div className="region-header-left d-flex align-items-center">
                          <a
                            href="https://business.balady.sa/"
                            className="b-business balady-app btn btn-primary"
                            aria-label="بلدي أعمال"
                            rel="nofollow noreferrer"
                            target="_blank"
                          >
                            بلدي أعمال
                          </a>
                          <div className="header-search headersearch_hide">
                            <button
                              type="button"
                              className="search-link"
                              id="searchBtn"
                              aria-label="بحث"
                              onClick={() => {
                                closeMobileNav();
                                setSearchOpen(true);
                              }}>
                              بحث
                            </button>
                          </div>

                          {searchOpen && (
                            <div
                              className="modal fade modal-search show"
                              id="headerSearch"
                              tabIndex="-1"
                              style={{ display: 'block' }}
                              role="dialog"
                              aria-modal="true"
                            >
                              <div className="modal-dialog">
                                <div className="modal-content">
                                  <div className="modal-header">
                                    <button
                                      type="button"
                                      className="btn-close modal-search-btn-close"
                                      aria-label="إغلاق"
                                      onClick={() => setSearchOpen(false)}
                                    />
                                  </div>
                                  <div className="modal-body">
                                    <div className="modal-search-content">
                                      <div className="search-api-form search">
                                        <form className="form-search" onSubmit={handleSearchSubmit}>
                                          <div className="form-item-search">
                                            <input
                                              className="form-control"
                                              type="text"
                                              name="search_api_fulltext"
                                              value={searchQuery}
                                              onChange={(e) => setSearchQuery(e.target.value)}
                                              placeholder="ابحث عن ما تريد"
                                              autoComplete="off"
                                            />
                                            <button type="submit" className="btn btn-primary btn-search">
                                              بحث
                                            </button>
                                          </div>
                                        </form>
                                        <a
                                          href="https://balady.gov.sa/solr-serach-v1"
                                          className="btn btn-outline-light btn-adv-search"
                                          target="_blank"
                                          rel="noopener noreferrer"
                                        >
                                          البحث المتقدم
                                        </a>
                                      </div>
                                      <div className="modal-search-suggestions">
                                        <div className="suggestions-content">
                                          <h2 className="text-suggestions">اقتراحات شائعة</h2>
                                          <div className="row g-3">
                                            <div className="col-auto">
                                              <a
                                                className="btn btn-light btn-sug"
                                                href="https://balady.gov.sa/products/10920"
                                                target="_blank"
                                                rel="noopener noreferrer"
                                              >
                                                الرخص التجارية
                                              </a>
                                            </div>
                                            <div className="col-auto">
                                              <a
                                                className="btn btn-light btn-sug"
                                                href="https://balady.gov.sa/products/10470"
                                                target="_blank"
                                                rel="noopener noreferrer"
                                              >
                                                الرخص الإنشائية
                                              </a>
                                            </div>
                                            <div className="col-auto">
                                              <a
                                                className="btn btn-light btn-sug"
                                                href="https://balady.gov.sa/services/10541"
                                                target="_blank"
                                                rel="noopener noreferrer"
                                              >
                                                حجز المواعيد الإلكترونية
                                              </a>
                                            </div>
                                          </div>
                                        </div>
                                      </div>
                                    </div>
                                  </div>
                                </div>
                              </div>
                            </div>
                          )}
                        </div>
                      </div>
                    </nav>
                  </div>
                </div>
              </div>
            </header>
          </nav>
        </div>
        <span className="clr" />
      </header>

      {searchOpen && (
        <div className="modal-backdrop fade show" onClick={() => setSearchOpen(false)} aria-hidden="true" />
      )}
    </div>
  );
};

export default Header;
